using System;using System.IO;using System.Linq;using System.Collections.Generic;using Game.Configs;using Game.Runtime;using Game.Skirmish.Contracts;using Newtonsoft.Json.Linq;
internal static class MetadataBindingControls{
 static bool resourcesBound;static int count;static readonly JArray checks=new JArray();static void Check(bool value,string name){if(!value)throw new Exception(name);count++;checks.Add(name);}static void Reject(Action action,string name){try{action();}catch(Exception e)when(e is InvalidDataException||e is InvalidOperationException||e is NotSupportedException){count++;checks.Add(name);return;}throw new Exception("Unexpected acceptance: "+name);}
 static SkirmishResolvedSetup Compile(JObject request,int seed){var g=JObject.Parse(File.ReadAllText((string)request["source_config_graph"]["path"]));var values=new SourceConfigMaterializer(g);var definition=values.ByPath<SkirmishScenarioDefinitionConfig>((string)g["definition_path"]);var catalog=values.ByPath<SkirmishExpansionCatalogConfig>("Assets/Game/Resources/SkirmishExpansionCatalog.asset");if(!resourcesBound){UnityEngine.Resources.BindSourceResources(new Dictionary<string,object>{{SkirmishExpansionCatalogConfig.ResourceName,catalog},{SkirmishSetupMatrixTable.PackagedResourceName,new UnityEngine.TextAsset(File.ReadAllText((string)request["setup_matrix"]["path"]))}});resourcesBound=true;}if(!SkirmishSetupMatrixTable.TryLoadPackaged(out var matrix,out string error))throw new Exception(error);var s=request["selection"];if(!SkirmishSetupCompiler.TryCompile(definition,(SkirmishDifficultyId)(int)s["difficulty_id"],(SkirmishSizeId)(int)s["size_id"],seed,new SkirmishContentManifest{RequiredFeatureIds=definition.RequiredFeatureIds??Array.Empty<string>()},matrix,out var setup,out var reasons))throw new Exception(string.Join(";",reasons));return setup;}
 static JObject Read(JToken d)=>JObject.Parse(File.ReadAllText((string)d["path"]));
 static void Main(string[] args){var request=JObject.Parse(File.ReadAllText(args[0]));string repo=args[1];var setup=Compile(request,1);var binding=SourceMetadataCompatibility.Load(request,setup,repo,repo);Check(binding.TargetSeed==1&&binding.TargetSetupHash==3589425631u,"actual_seed1_compiler_context");Check((int)binding.Receipt()["captured_seed"]==104731,"captured_provenance_retained");
 var dd=request["building_definitions"];var ud=request["unit_production_metadata"];var sd=request["building_request_metadata"];var definitions=Read(dd);var units=Read(ud);var supplement=Read(sd);
 Reject(()=>GeneratedBuildingDefinitions.Load((string)dd["path"],(string)dd["sha256"],setup.SetupHash,new Dictionary<string,Unity.Entities.Entity>()),"default_building_reader_rejects_cross_context");
 var loaded=GeneratedBuildingDefinitions.Load((string)dd["path"],(string)dd["sha256"],setup.SetupHash,new Dictionary<string,Unity.Entities.Entity>(),binding);Check(loaded.Definitions.Count==8,"bound_building_reader_eight_actual_rows");
 Reject(()=>GeneratedUnitProductionMetadata.Load((string)ud["path"],(string)ud["sha256"],setup.SetupHash,1,repo,loaded.Assets,new Dictionary<string,Unity.Entities.Entity>(),loaded.AssetIdentities),"default_unit_reader_rejects_cross_context");
 var actualUnits=GeneratedUnitProductionMetadata.Load((string)ud["path"],(string)ud["sha256"],setup.SetupHash,1,repo,loaded.Assets,new Dictionary<string,Unity.Entities.Entity>(),loaded.AssetIdentities,binding);Check(actualUnits.Ordered.Count==12&&actualUnits.Ordered.All(x=>!x.HasActualTemplate),"bound_unit_reader_twelve_metadata_rows_no_template_state");binding.RequireConfigured(definitions,supplement);Check(true,"configured_native_provider_requestability_and_indices");
 var changed=(JObject)definitions.DeepClone();changed["definitions"][0]["prefab"]["guid"]=definitions["definitions"][1]["prefab"]["guid"].DeepClone();Reject(()=>binding.RequireDefinitions((string)dd["sha256"],changed),"wrong_existing_prefab_guid");changed=(JObject)definitions.DeepClone();changed["definitions"][0]["prefab"]["local_id"]=-123;Reject(()=>binding.RequireDefinitions((string)dd["sha256"],changed),"wrong_prefab_local_id");changed=(JObject)definitions.DeepClone();changed["definitions"][0]["fields"]["MaxHealth"]["value"]="1201";Reject(()=>binding.RequireDefinitions((string)dd["sha256"],changed),"wrong_definition_value");changed=(JObject)definitions.DeepClone();changed["seed"]=1;changed["setup_hash"]=setup.SetupHash;Reject(()=>binding.RequireDefinitions((string)dd["sha256"],changed),"relabelled_historical_provenance");
 var sc=(JObject)supplement.DeepClone();sc["rows"][0]["can_request"]=!(bool)sc["rows"][0]["can_request"];Reject(()=>binding.RequireConfigured(definitions,sc),"wrong_requestability");sc=(JObject)supplement.DeepClone();sc["rows"][0]["scene_catalog_index"]=123;Reject(()=>binding.RequireConfigured(definitions,sc),"wrong_provider_index");
 var uc=(JObject)units.DeepClone();uc["units"][0]["production_metadata"]["fields"]["ProductionDurationSeconds"]["bits"]="3f800000";Reject(()=>binding.RequireUnits((string)ud["sha256"],uc),"wrong_unit_recipe_duration");uc=(JObject)units.DeepClone();JToken first=uc["units"][0].DeepClone();uc["units"][0]=uc["units"][1].DeepClone();uc["units"][1]=first;Reject(()=>binding.RequireUnits((string)ud["sha256"],uc),"wrong_unit_order");
 var rc=(JObject)request.DeepClone();rc["metadata_compatibility"]["sha256"]=new string('0',64);Reject(()=>SourceMetadataCompatibility.Load(rc,setup,repo,repo),"unqualified_native_reference");Reject(()=>SourceMetadataCompatibility.Load(request,Compile(request,2),repo,repo),"unqualified_compiled_seed2");var corrupt=Compile(request,1);corrupt.SetupHash^=1;Reject(()=>SourceMetadataCompatibility.Load(request,corrupt,repo,repo),"wrong_compiled_setup_hash");
 string fake=Path.Combine(Path.GetDirectoryName(args[2]),"wrong-script-meta-root-"+Path.GetFileNameWithoutExtension(args[2]));string metaSource="Assets/Game/Scripts/Authorings/BuildingDefinitionAuthoring.cs";Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(fake,metaSource)));File.Copy(Path.Combine(repo,metaSource),Path.Combine(fake,metaSource));File.WriteAllText(Path.Combine(fake,metaSource+".meta"),File.ReadAllText(Path.Combine(repo,metaSource+".meta")).Replace("guid:","changed_guid:"));Reject(()=>SourceMetadataCompatibility.Load(request,setup,fake,repo),"changed_script_guid_rejected_before_binding");
 var same=SourceMetadataCompatibility.Load(request,Compile(request,104731),repo,repo);Check(same.TargetSeed==104731,"original_context_also_exact");Reject(()=>GeneratedBuildingDefinitions.Load((string)dd["path"],(string)dd["sha256"],setup.SetupHash^1,new Dictionary<string,Unity.Entities.Entity>(),binding),"bound_building_reader_wrong_target_setup");Reject(()=>GeneratedUnitProductionMetadata.Load((string)ud["path"],(string)ud["sha256"],setup.SetupHash^1,1,repo,loaded.Assets,new Dictionary<string,Unity.Entities.Entity>(),loaded.AssetIdentities,binding),"bound_unit_reader_wrong_target_setup");Reject(()=>GeneratedUnitProductionMetadata.Load((string)ud["path"],(string)ud["sha256"],setup.SetupHash,104731,repo,loaded.Assets,new Dictionary<string,Unity.Entities.Entity>(),loaded.AssetIdentities,binding),"bound_unit_reader_wrong_target_seed");Reject(()=>binding.RequireConfigured(definitions,supplement,setup.SetupHash^1,1),"configured_reader_wrong_target_setup");Reject(()=>binding.RequireConfigured(definitions,supplement,setup.SetupHash,104731),"configured_reader_wrong_target_seed");binding.VerifyUnchanged();Check(true,"dependency_census_after_controls");var result=new JObject{["passed"]=count,["checks"]=checks,["binding"]=binding.Receipt(),["scope"]="Original compiler and all three reader mechanisms only; no World, seed admission, positions or state transfer"};File.WriteAllText(args[2],result.ToString());Console.WriteLine("[MetadataBindingControls] result=Passed checks="+count);}
